def validate_acceptance(receipt,confirmation):
    exact(confirmation,CONFIRMATION,'confirmation changed')
    exact({k:v for k,v in receipt.items() if k!='text'},RECEIPT,'receipt fields changed')
    raw=receipt['text'].encode('utf-8')
    if sha(raw)!=RECEIPT['sha256'] or len(raw)!=RECEIPT['size_bytes']:raise ValueError('complete user message changed')
    return True

def missing_platform_inputs(item_id):
    return [{'id':item_id+'@'+platform,'platform':platform,'status':'required-native-input-not-bound','availability':None,'resolved_path':None,'version':None,'architecture':None,'package_record':None,'sha256':None,'size_bytes':None,'owner_mode':None,'interpreter_loader_library_graph':None,'effective_config_and_hook_bytes':None,'checked_to_consumed_identity':None,'fresh_attempt_identity':None,'independent_raw_observation':None,'native_proof':False} for platform in PLATFORMS]

def occurrence_records(views,names,review):
    result=[]
    patterns={name:re.compile(r'(?<![A-Za-z0-9_])'+re.escape(name)+r'(?![A-Za-z0-9_])') for name in names}
    for source_index,binding in enumerate(SOURCE_BINDINGS):
        for line_number,line in enumerate(views[binding['path']][1],1):
            text=line.decode('utf-8')
            for name in names:
                matches=list(patterns[name].finditer(text))
                if not matches:continue
                loc=anchor(views,source_index,line_number)
                prior_contexts=[{'site_id':site['id'],'context_review':site['context_review']} for site in review['selected_sites'] if site['anchor']['path']==loc['path'] and site['anchor']['line_number']==line_number]
                result.append({'id':len(result),'name_candidate':name,'anchor':loc,'literal_match_byte_ranges':[[len(text[:m.start()].encode('utf-8')),len(text[:m.end()].encode('utf-8'))] for m in matches],'selected362_contexts':prior_contexts,'status':'lexical-name-occurrence-not-command-resolution','actual_callee_binding':None,'native_dependency_proven':False})
                if len(result)>MAX_OCCURRENCES:raise ValueError('dependency occurrence budget exceeded; no successful partial register')
    return result

def dependency_register(sources,inventory,review,gap_rows):
    views=source_lines(sources)
    if canonical(inventory)!=INVENTORY_SHA:raise ValueError('accepted361 full inventory changed')
    if canonical(review)!=REVIEW_SHA:raise ValueError('accepted362 context review changed')
    if canonical(gap_rows)!=GAP_ROWS_SHA:raise ValueError('original native gap rows changed')
    occurrences=occurrence_records(views,COMMAND_NAMES,review)
    commands=[]
    for name in COMMAND_NAMES:
        ids=[row['id'] for row in occurrences if row['name_candidate']==name]
        if not ids:raise ValueError('reviewed candidate has no bound source occurrence')
        commands.append({'id':'name:'+name,'name_candidate':name,'occurrence_ids':ids,'classification':'written-external-name-candidate-not-resolved-native-command','exhaustive':False,'required_inputs':COMMON_REQUIREMENTS,'platform_inputs':missing_platform_inputs('name:'+name)})
    families=[]
    for key,sites,gaps,requirements in FAMILY_SPECS:
        anchors=[]
        for source_index,line,token,literal in sites:
            loc=anchor(views,source_index,line)
            if loc['full_line_text'].rstrip('\n')!=literal or token not in literal:raise ValueError('reviewed family source line changed')
            anchors.append({'token':token,'anchor':loc,'status':'source-context-input-requirement-not-runtime-proof'})
        families.append({'id':key,'source_anchors':anchors,'original_native_gap_ids':gaps,'required_inputs':requirements,'platform_inputs':missing_platform_inputs('family:'+key),'gap_discharged':False})
    report = {'schema':1,'step':363,'scope':'repository-source-inventory-and-roadmap-workstream359-368-only','review_sources':SOURCE_BINDINGS,'frozen_inputs':{'inventory_canonical_sha256':INVENTORY_SHA,'review_canonical_sha256':REVIEW_SHA,'native_gap_rows_canonical_sha256':GAP_ROWS_SHA},'command_candidates':commands,'literal_occurrences':occurrences,'dependency_families':families,'full_original_native_gap_rows348':gap_rows,'platforms':list(PLATFORMS),'unresolved_relations':UNRESOLVED,'coverage':{'named_candidates':len(commands),'dependency_families':len(families),'literal_occurrences':len(occurrences),'max_literal_occurrences':MAX_OCCURRENCES,'candidate_register_is_exhaustive':False,'all15106_inventory_records_retained':True,'shell_parsed':False,'native_resolution_performed':False,'installed_versions_bound':False,'platform_inputs_independently_observed':False,'missing_input_means_absent':False,'postinst_off_discharges_hook_closure':False,'historical_constants_are_current_bindings':False,'decoded_payloads_reviewed':False,'remaining_runtime_dependencies_status':'required-not-enumerated-or-bound'},'boundaries':BOUNDARIES}
    # Detach all mutable output from frozen module data and caller inputs.
    return json.loads(json.dumps(report,sort_keys=True,ensure_ascii=True))

def validate_register(report,sources,inventory,review,gap_rows):
    return exact(report,dependency_register(sources,inventory,review,gap_rows),'dependency data changed or missing native input promoted')
